// ---- host logic: examples/api_tours/media_lottie/host.cpp ----
// API tour (C++ Wrapper): game audio, media elements and Lottie. Same page, checks and case as
// examples/c/ports/kui_api_media_lottie.c (and the Go / Rust ports): at start-up the host drives
// the document's AudioManager (play by path into groups, per-handle volume / pan / pitch / pause /
// seek, group volume and mute, pause-all / stop-all, preload / unload, counts), an <audio> and a
// <video> element (Element::media*: src, load, loop / autoplay / muted / volume flags, seek, play /
// pause, network and ready state) and a <lottie-player> (Element::lottie*: state, natural size,
// speed, loop, pause, seek, stop), checking every call against the state read back. Time-dependent
// results are read from timers once frames have run; #tour-result ends as "PASS n/n". Works
// without an audio device (KUI_MEDIA_NO_DEVICE=1): the checks read state, they do not listen.
//
// Paths: the C++ tour loads its page from a string, so the media paths are absolute, built from
// the executable's directory (assets/ next to it, as for the C runner): tour_executable_dir().
//
// Wrapper differences handled here (the checks compare the equivalent Wrapper result):
//   * Failing setters / getters throw kui::Error; status() is the C status.
//   * AudioManager::play / preload drop the C status: a refused play returns handle 0 and preload
//     returns 0 loaded (C: KUI_ERR_NOT_SUPPORTED / KUI_ERR_IO with handle 0).
//   * AudioManager::info() returns a SoundInfo with handle 0 where kui_document_audio_get_info
//     fails (unknown / stopped handle).

#include <cmath>
#include <cstdarg>
#include <functional>
#include <sstream>

#ifdef _WIN32
#ifndef NOMINMAX
#define NOMINMAX
#endif
#ifndef WIN32_LEAN_AND_MEAN
#define WIN32_LEAN_AND_MEAN
#endif
#include <windows.h>
#elif defined(__APPLE__)
#include <mach-o/dyld.h>
#else
#include <unistd.h>
#endif

namespace {

kui::Document* g_doc = nullptr;

// ---- Self-check bookkeeping: count, log one <tr> per check, publish the verdict ----------

int g_total = 0;
int g_failed = 0;
int g_known = 0;
std::string g_failed_names;

std::string fmt(const char* format, ...) {
    char buffer[512];
    va_list args;
    va_start(args, format);
    std::vsnprintf(buffer, sizeof buffer, format, args);
    va_end(args);
    return buffer;
}

void log_row(const std::string& name, const std::string& result, const std::string& cell) {
    kui::Element* log = g_doc->getElementById("tour-log");
    if (!log) return;
    auto row = g_doc->createElement("tr");
    row->setAttribute("data-check", name);
    row->setAttribute("data-result", result);
    if (result != "ok") row->addClass("bad");
    auto first = g_doc->createElement("td");
    first->setTextContent(name);
    row->appendChild(first);
    auto second = g_doc->createElement("td");
    second->setTextContent(cell);
    row->appendChild(second);
    log->appendChild(row);
}

void check(const std::string& name, bool ok, const std::string& detail) {
    g_total++;
    if (ok) {
        log_row(name, "ok", "ok");
        return;
    }
    g_failed++;
    g_failed_names += (g_failed_names.empty() ? "" : ", ") + name;
    std::fprintf(stderr, "tour check failed: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "fail", "FAIL: " + detail);
}

// A documented behaviour the engine currently gets wrong: logged, not counted.
void known(const std::string& name, bool ok, const std::string& bug, const std::string& detail) {
    if (ok) {
        g_total++;
        log_row(name, "ok", "ok");
        return;
    }
    g_known++;
    std::fprintf(stderr, "tour known bug: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "known", "KNOWN BUG: " + bug + " (" + detail + ")");
}

void finish() {
    kui::Element* result = g_doc->getElementById("tour-result");
    if (!result) return;
    std::string text = g_failed == 0 ? fmt("PASS %d/%d", g_total, g_total)
                                     : fmt("FAIL %d/%d: ", g_failed, g_total) + g_failed_names;
    if (g_known) text += fmt(" (known bugs: %d)", g_known);
    result->setTextContent(text);
    result->setAttribute("data-total", std::to_string(g_total));
    result->setAttribute("data-failed", std::to_string(g_failed));
    result->setAttribute("data-known", std::to_string(g_known));
    result->addClass(g_failed == 0 ? "pass" : "fail");
}

// A Wrapper method that throws (kui::Error) fails its group instead of aborting the tour.
void run_group(const char* group, const std::function<void()>& body) {
    try {
        body();
    } catch (const std::exception& error) {
        check(std::string(group) + ".exception", false, error.what());
    }
}

// Status of a Wrapper call: KUI_OK, or the status of the kui::Error it throws.
KuiStatus status_of(const std::function<void()>& call) {
    try {
        call();
        return KUI_OK;
    } catch (const kui::Error& error) {
        return error.status();
    }
}

// ---- Paths: the bundled media sit in assets/ next to the executable ----------------------

std::string g_mp3;
std::string g_mp4;
std::string g_lottie;
std::string g_missing;

void find_paths() {
    const std::string dir = tour_executable_dir();
    g_mp3 = dir + "/assets/native_media/sample.mp3";
    g_mp4 = dir + "/assets/native_media/sample.mp4";
    g_lottie = dir + "/assets/native_animation/pulse.json";
    g_missing = dir + "/assets/native_media/no_such_sound.mp3";
}

// ---- Small helpers ----------------------------------------------------------------------

kui::AudioManager& audio() { return g_doc->audioManager(); }

bool near_f(double a, double b, double tolerance) { return std::fabs(a - b) <= tolerance; }

void set_text(const char* id, const std::string& text) {
    if (kui::Element* element = g_doc->getElementById(id)) element->setTextContent(text);
}

const char* group_name(kui::AudioGroup group) {
    switch (group) {
        case kui::AudioGroup::Master: return "master";
        case kui::AudioGroup::Music: return "music";
        case kui::AudioGroup::SFX: return "sfx";
        default: return "ui";
    }
}

kui::PlayOptions play_options(kui::AudioGroup group, float volume, float pan, float pitch, bool loop) {
    kui::PlayOptions options;
    options.group = group;
    options.volume = volume;
    options.pan = pan;
    options.pitch = pitch;
    options.loop = loop;
    return options;
}

// ---- Game audio: availability, one looping music sound, sfx, groups, pool --------------

bool g_audio_available = false;
kui::SoundHandle g_music = 0;   // the looping music handle the buttons drive
const double g_music_seek_to = 1.5;

void check_audio_groups() {
    // Group volume / mute live in the manager and work with or without a device.
    audio().setGroupVolume(kui::AudioGroup::Music, 0.4f);
    audio().setGroupMuted(kui::AudioGroup::Music, true);
    const float volume = audio().groupVolume(kui::AudioGroup::Music);
    const bool muted = audio().isGroupMuted(kui::AudioGroup::Music);
    const KuiStatus bad_volume = status_of([] { audio().setGroupVolume(kui::AudioGroup::Music, 2.0f); });
    const KuiStatus bad_group = status_of([] { audio().groupVolume(static_cast<kui::AudioGroup>(7)); });
    audio().setGroupMuted(kui::AudioGroup::Music, false);
    audio().setGroupVolume(kui::AudioGroup::Music, 1.0f);
    const float restored = audio().groupVolume(kui::AudioGroup::Music);
    const bool restored_muted = audio().isGroupMuted(kui::AudioGroup::Music);
    check("audio.set_group", near_f(volume, 0.4, 0.001) && muted && bad_volume == KUI_ERR_INVALID_ARG &&
              bad_group == KUI_ERR_INVALID_ARG && near_f(restored, 1.0, 0.001) && !restored_muted,
          fmt("music 0.4/muted -> %.2f/%d, volume 2 status %d, group 7 status %d, restored %.2f/%d",
              volume, muted, bad_volume, bad_group, restored, restored_muted));
}

void check_audio_unavailable() {
    const kui::SoundHandle handle = audio().play(g_mp3, play_options(kui::AudioGroup::SFX, 1.0f, 0.0f, 1.0f, false));
    const kui::u32 loaded = audio().preload(g_mp3, 2);
    check("audio.play-unavailable", handle == 0 && loaded == 0,
          fmt("play handle %u, preload loaded %u", handle, loaded));
}

void check_audio_handles() {
    const kui::u32 loaded = audio().preload(g_mp3, 2);
    const kui::u32 pooled = audio().pooledCount();
    check("audio.preload", loaded == 2 && pooled >= 2, fmt("loaded %u pooled %u", loaded, pooled));

    g_music = audio().play(g_mp3, play_options(kui::AudioGroup::Music, 0.5f, -0.5f, 1.25f, true));
    kui::SoundInfo info = audio().info(g_music);
    check("audio.play", g_music != 0 && info.handle == g_music && info.group == kui::AudioGroup::Music &&
              near_f(info.volume, 0.5, 0.001) && near_f(info.pan, -0.5, 0.001) &&
              near_f(info.pitch, 1.25, 0.001) && info.looping && info.playing && info.path == g_mp3,
          fmt("handle %u group %s vol %.2f pan %.2f pitch %.2f loop %d playing %d", g_music,
              group_name(info.group), info.volume, info.pan, info.pitch, info.looping, info.playing));

    audio().setVolume(g_music, 0.3f);
    audio().setPan(g_music, 0.7f);
    audio().setPitch(g_music, 0.8f);
    info = audio().info(g_music);
    check("audio.set_volume_pan_pitch", near_f(info.volume, 0.3, 0.001) && near_f(info.pan, 0.7, 0.001) &&
              near_f(info.pitch, 0.8, 0.001),
          fmt("vol %.2f pan %.2f pitch %.2f", info.volume, info.pan, info.pitch));

    audio().pause(g_music);
    const bool paused_playing = audio().isPlaying(g_music);
    audio().resume(g_music);
    const bool resumed_playing = audio().isPlaying(g_music);
    check("audio.set_paused", !paused_playing && resumed_playing,
          fmt("playing while paused %d, after resume %d", paused_playing, resumed_playing));

    const KuiStatus status = status_of([] { audio().seek(g_music, g_music_seek_to); });
    const KuiStatus bad = status_of([] { audio().seek(g_music, -1.0); });
    check("audio.seek-args", status == KUI_OK && bad == KUI_ERR_INVALID_ARG,
          fmt("seek status %d, seek(-1) status %d", status, bad));

    const kui::SoundHandle missing = audio().play(g_missing);
    check("audio.play-missing-file", missing == 0, fmt("handle %u", missing));
}

kui::SoundHandle g_sfx[2];

void check_audio_bulk() {
    const kui::PlayOptions sfx = play_options(kui::AudioGroup::SFX, 0.2f, 0.0f, 1.0f, false);
    g_sfx[0] = audio().play(g_mp3, sfx);
    g_sfx[1] = audio().play(g_mp3, sfx);
    kui::u32 music_active = audio().activeCount(kui::AudioGroup::Music);
    kui::u32 sfx_active = audio().activeCount(kui::AudioGroup::SFX);
    const kui::u32 all_active = audio().activeCount();
    check("audio.get_counts", music_active == 1 && sfx_active == 2 && all_active == 3,
          fmt("music %u sfx %u all %u", music_active, sfx_active, all_active));

    audio().pauseAll(kui::AudioGroup::Music);
    const bool paused_playing = audio().isPlaying(g_music);
    const bool sfx_playing = audio().isPlaying(g_sfx[0]);
    audio().resumeAll();
    const bool resumed_playing = audio().isPlaying(g_music);
    check("audio.set_all_paused", !paused_playing && sfx_playing && resumed_playing,
          fmt("music while group paused %d, sfx %d, music after resume all %d", paused_playing,
              sfx_playing, resumed_playing));

    audio().stopAll(kui::AudioGroup::SFX);
    sfx_active = audio().activeCount(kui::AudioGroup::SFX);
    music_active = audio().activeCount(kui::AudioGroup::Music);
    check("audio.stop_all", sfx_active == 0 && music_active == 1, fmt("sfx %u music %u", sfx_active, music_active));
}

// Once frames have run: the seek landed and the position moves; then stop and unload.
void check_audio_late() {
    kui::SoundInfo info = audio().info(g_music);
    check("audio.get_info-time", info.duration > 1.0 && info.currentTime > g_music_seek_to - 0.05,
          fmt("duration %.2f current %.2f (seeked to %.2f)", info.duration, info.currentTime, g_music_seek_to));

    const kui::SoundHandle stopped = g_music;
    audio().stop(g_music);
    info = audio().info(stopped);
    const kui::u32 music_active = audio().activeCount(kui::AudioGroup::Music);
    check("audio.stop", (info.handle == 0 || !info.playing) && music_active == 0,
          fmt("info handle %u playing %d, music active %u", info.handle, info.playing, music_active));
    const KuiStatus status = status_of([] { audio().stop(987654u); });
    check("audio.stop-unknown", status == KUI_OK, fmt("status %d", status));

    const kui::u32 pooled_before = audio().pooledCount();
    audio().unload(g_mp3);
    const kui::u32 pooled_after = audio().pooledCount();
    audio().unloadAll();
    check("audio.unload", pooled_before > 0 && pooled_after == 0 && audio().pooledCount() == 0,
          fmt("pooled %u -> %u after unload(path), %u after unloadAll()", pooled_before, pooled_after,
              audio().pooledCount()));
    g_music = 0;
}

void check_audio() {
    bool available = false;
    const KuiStatus status = status_of([&] { available = audio().isAvailable(); });
    g_audio_available = status == KUI_OK && available;
    // Recorded as is: with KUI_MEDIA_NO_DEVICE=1 the plugin runs without a device.
    check("audio.is_available", status == KUI_OK, fmt("status %d available %d", status, available));
    set_text("au-avail", fmt("available=%d", status == KUI_OK ? (available ? 1 : 0) : -1));
    check_audio_groups();
    if (!g_audio_available) {
        check_audio_unavailable();
        return;
    }
    check_audio_handles();
    check_audio_bulk();
}

// ---- Media elements: flags, volume, mute, src / load, seek, play / pause ---------------

kui::HTMLMediaElement* g_aud = nullptr;
kui::HTMLMediaElement* g_vid = nullptr;

// Readers that report -1 when the call fails (like the C version's initial values).
double media_time(kui::HTMLMediaElement* media) {
    try {
        return media->mediaCurrentTime();
    } catch (const kui::Error&) {
        return -1;
    }
}

int media_paused(kui::HTMLMediaElement* media) {
    try {
        return media->mediaPaused() ? 1 : 0;
    } catch (const kui::Error&) {
        return -1;
    }
}

void check_media_setup(const std::string& name, kui::HTMLMediaElement* media, const std::string& src) {
    int state = media->mediaNetworkState();
    check(name + ".network_state-empty", state == 0,
          fmt("networkState %d before src (expected 0 NETWORK_EMPTY)", state));

    media->mediaSetLoop(true);
    media->mediaSetAutoplay(false);
    const bool loop = media->mediaLoop(), autoplay = media->mediaAutoplay(), ended = media->mediaEnded();
    check(name + ".playback_flags", loop && !autoplay && !ended,
          fmt("loop %d autoplay %d ended %d", loop, autoplay, ended));

    media->mediaSetMuted(true);
    const bool muted_on = media->mediaMuted();
    media->mediaSetMuted(false);
    const bool muted_off = media->mediaMuted();
    media->mediaSetVolume(0.4f);
    const float volume = media->mediaVolume();
    check(name + ".muted_volume", muted_on && !muted_off && near_f(volume, 0.4, 0.001),
          fmt("muted on %d off %d, volume %.2f", muted_on, muted_off, volume));

    const bool available = media->mediaAvailable();
    media->mediaSetSrc(src);
    const KuiStatus status = status_of([media] { media->mediaLoad(); });
    state = media->mediaNetworkState();
    check(name + ".load", status == KUI_OK && state == 2 && media_paused(media) == 1 && media_time(media) == 0.0,
          fmt("status %d networkState %d (expected 2 LOADING) paused %d available %d", status, state,
              media_paused(media), available));
}

void check_media_not_media() {
    kui::Element* plain = g_doc->getElementById("plain");
    const KuiStatus media_status = plain ? status_of([plain] { plain->mediaPaused(); }) : KUI_ERR_NOT_FOUND;
    const KuiStatus lottie_status = plain ? status_of([plain] { plain->lottieState(); }) : KUI_ERR_NOT_FOUND;
    check("media.not_media_element", media_status == KUI_ERR_NOT_SUPPORTED && lottie_status == KUI_ERR_NOT_SUPPORTED,
          fmt("mediaPaused status %d, lottieState status %d", media_status, lottie_status));
}

// A second after load(): metadata should be there without playing (HTML load()).
void check_media_metadata(const std::string& name, kui::HTMLMediaElement* media) {
    const double duration = media->mediaDuration();
    const int ready = media->mediaReadyState();
    known(name + ".metadata-before-play", duration > 0 && ready >= 1,
          "media load lazily on the first play(): load() leaves readyState 0 and duration 0",
          fmt("duration %.2f readyState %d a second after load()", duration, ready));
}

// Play loads the file: duration, network / ready state; then seek while playing.
void check_media_play(const std::string& name, kui::HTMLMediaElement* media, double seek_to) {
    media->mediaPlay();
    const double duration = media->mediaDuration();
    const int network = media->mediaNetworkState();
    const int ready = media->mediaReadyState();
    check(name + ".play", media_paused(media) == 0 && duration > seek_to + 1.0 && network == 1 && ready >= 1,
          fmt("paused %d duration %.2f networkState %d readyState %d", media_paused(media), duration,
              network, ready));

    media->mediaSetCurrentTime(seek_to);
    const double after_seek = media_time(media);
    check(name + ".set_current_time", near_f(after_seek, seek_to, 0.3),
          fmt("currentTime %.2f right after seek to %.2f", after_seek, seek_to));
}

// A while after the seek: playback continues from there; pause holds it.
void check_media_playing(const std::string& name, kui::HTMLMediaElement* media, double seek_to, bool seek_bug) {
    const double now = media_time(media);
    if (seek_bug) {
        known(name + ".current_time-after-seek", now >= seek_to && now < seek_to + 60.0,
              "seeking an <audio> element never reaches the player: playback goes on from the old "
              "position and currentTime falls back to it",
              fmt("currentTime %.2f, seeked to %.2f", now, seek_to));
    } else {
        check(name + ".current_time-after-seek", now >= seek_to && now < seek_to + 5.0,
              fmt("currentTime %.2f, seeked to %.2f", now, seek_to));
    }
    media->mediaPause();
    const int paused = media_paused(media);
    check(name + ".pause", paused == 1 && media_time(media) > 0,
          fmt("paused %d currentTime %.2f", paused, media_time(media)));
}

// ---- Lottie: load, state, speed / loop, pause / seek / stop ---------------------------

kui::HTMLLottieElement* g_lot = nullptr;

KuiCLottieState lottie_state() {
    try {
        return g_lot->lottieState();
    } catch (const kui::Error&) {
        return KuiCLottieState{};
    }
}

double g_lottie_mark = 0;

void check_lottie_loaded() {
    const KuiCLottieState state = lottie_state();
    const kui::Size size = g_lot->lottieNaturalSize();
    check("lottie.get_state-loaded", state.load_state == KUI_C_LOTTIE_COMPLETE && state.playing &&
              near_f(state.speed, 1.0, 0.001),
          fmt("load %d playing %d speed %.2f", state.load_state, state.playing, state.speed));
    check("lottie.get_natural_size", near_f(size.width, 200, 0.5) && near_f(size.height, 200, 0.5),
          fmt("%.0fx%.0f (pulse.json is 200x200)", size.width, size.height));
    g_lottie_mark = state.position;
}

void check_lottie_controls() {
    const KuiCLottieState state = lottie_state();
    check("lottie.position-advances", state.position != g_lottie_mark,
          fmt("position %.3f then %.3f", g_lottie_mark, state.position));

    g_lot->lottieSetSpeed(2.0f);
    KuiCLottieState after = lottie_state();
    const KuiStatus bad = status_of([] { g_lot->lottieSetSpeed(-1.0f); });
    check("lottie.set_speed", near_f(after.speed, 2.0, 0.001) && bad == KUI_ERR_INVALID_ARG,
          fmt("speed %.2f, speed -1 status %d", after.speed, bad));
    g_lot->lottieSetSpeed(1.0f);

    g_lot->lottieSetLoop(false);
    const int off = lottie_state().looping;
    g_lot->lottieSetLoop(true);
    after = lottie_state();
    check("lottie.set_loop", off == 0 && after.looping == 1, fmt("loop off %d, on %d", off, after.looping));

    g_lot->lottiePause();
    g_lot->lottieSeek(0.5);
    after = lottie_state();
    check("lottie.pause_seek", !after.playing && near_f(after.position, 0.5, 0.02),
          fmt("playing %d position %.3f", after.playing, after.position));
}

void check_lottie_held() {
    const KuiCLottieState state = lottie_state();
    check("lottie.paused-holds", !state.playing && near_f(state.position, 0.5, 0.02),
          fmt("playing %d position %.3f after a while", state.playing, state.position));
    g_lot->lottieStop();
    const KuiCLottieState stopped = lottie_state();
    check("lottie.stop", !stopped.playing && near_f(stopped.position, 0.0, 0.001),
          fmt("playing %d position %.3f", stopped.playing, stopped.position));
    g_lot->lottiePlay();   // leave it playing for the panel
}

// ---- Phases: immediate calls, then timers for results that need frames -----------------

const double kAudioSeek = 300.0;   // far from where playback is after a second (the file is 675 s)
const double kVideoSeek = 5.0;     // the clip is 13.3 s

void phase_three() {
    run_group("audio", [] { check_media_playing("audio", g_aud, kAudioSeek, true); });
    run_group("video", [] { check_media_playing("video", g_vid, kVideoSeek, false); });
    run_group("lottie", check_lottie_held);
    if (g_audio_available) run_group("audio", check_audio_late);
    finish();
}

void phase_two() {
    run_group("audio", [] { check_media_metadata("audio", g_aud); });
    run_group("video", [] { check_media_metadata("video", g_vid); });
    run_group("audio", [] { check_media_play("audio", g_aud, kAudioSeek); });
    run_group("video", [] { check_media_play("video", g_vid, kVideoSeek); });
    run_group("lottie", check_lottie_controls);
    kui::Platform::setTimeout([] { phase_three(); }, 700);
}

void phase_one() {
    run_group("lottie", check_lottie_loaded);
    kui::Platform::setTimeout([] { phase_two(); }, 900);
}

// ---- Panel buttons ----------------------------------------------------------------------

bool g_au_paused = false, g_au_quiet = false, g_au_right = false, g_au_fast = false;
bool g_au_all_paused = false, g_au_muted = false;

void report_audio() {
    const kui::SoundInfo info = audio().info(g_music);
    if (g_music != 0 && info.handle == g_music) {
        set_text("au-out", fmt("music #%u playing=%d vol=%.2f pan=%.2f pitch=%.2f loop=%d t=%.1f/%.1f",
                               g_music, info.playing, info.volume, info.pan, info.pitch, info.looping,
                               info.currentTime, info.duration));
    } else {
        set_text("au-out", fmt("music: none (handle %u)", g_music));
    }
    set_text("au-counts", fmt("active=%u sfx=%u pooled=%u music-group=%.1f%s", audio().activeCount(),
                              audio().activeCount(kui::AudioGroup::SFX), audio().pooledCount(),
                              audio().groupVolume(kui::AudioGroup::Music),
                              audio().isGroupMuted(kui::AudioGroup::Music) ? " muted" : ""));
}

void on_au_play() {
    audio().stop(g_music);
    g_music = audio().play(g_mp3, play_options(kui::AudioGroup::Music, 1.0f, 0.0f, 1.0f, true));
    g_au_paused = g_au_quiet = g_au_right = g_au_fast = false;
    report_audio();
}

void on_au_pause() {
    g_au_paused = !g_au_paused;
    if (g_au_paused) audio().pause(g_music);
    else audio().resume(g_music);
    report_audio();
}

void on_au_volume() {
    g_au_quiet = !g_au_quiet;
    audio().setVolume(g_music, g_au_quiet ? 0.3f : 1.0f);
    report_audio();
}

void on_au_pan() {
    g_au_right = !g_au_right;
    audio().setPan(g_music, g_au_right ? 1.0f : -1.0f);
    report_audio();
}

void on_au_pitch() {
    g_au_fast = !g_au_fast;
    audio().setPitch(g_music, g_au_fast ? 1.5f : 1.0f);
    report_audio();
}

void on_au_seek() {
    audio().seek(g_music, 2.0);
    report_audio();
}

void on_au_stop() {
    audio().stop(g_music);
    report_audio();
}

void on_au_sfx() {
    const kui::PlayOptions sfx = play_options(kui::AudioGroup::SFX, 0.3f, 0.0f, 1.0f, false);
    audio().play(g_mp3, sfx);
    audio().play(g_mp3, sfx);
    report_audio();
}

void on_au_stopsfx() {
    audio().stopAll(kui::AudioGroup::SFX);
    report_audio();
}

void on_au_pauseall() {
    g_au_all_paused = !g_au_all_paused;
    if (g_au_all_paused) audio().pauseAll();
    else audio().resumeAll();
    report_audio();
}

void on_au_mute() {
    g_au_muted = !g_au_muted;
    audio().setGroupVolume(kui::AudioGroup::Music, g_au_muted ? 0.5f : 1.0f);
    audio().setGroupMuted(kui::AudioGroup::Music, g_au_muted);
    report_audio();
}

void on_au_preload() {
    audio().preload(g_mp3, 3);
    report_audio();
}

void on_au_unload() {
    audio().unloadAll();
    report_audio();
}

void report_lottie() {
    const KuiCLottieState state = lottie_state();
    set_text("lot-out", fmt("playing=%d loop=%d speed=%.1f position=%.2f load=%d", state.playing,
                            state.looping, state.speed, state.position, state.load_state));
}

bool g_lot_fast = false;

void on_lot_play() { g_lot->lottiePlay(); report_lottie(); }
void on_lot_pause() { g_lot->lottiePause(); report_lottie(); }
void on_lot_seek0() { g_lot->lottieSeek(0.0); report_lottie(); }
void on_lot_seek50() { g_lot->lottieSeek(0.5); report_lottie(); }
void on_lot_stop() { g_lot->lottieStop(); report_lottie(); }

void on_lot_speed() {
    g_lot_fast = !g_lot_fast;
    g_lot->lottieSetSpeed(g_lot_fast ? 2.0f : 1.0f);
    report_lottie();
}

void on_lot_loop() {
    g_lot->lottieSetLoop(!lottie_state().looping);
    report_lottie();
}

void report_media(const char* id, kui::HTMLMediaElement* media) {
    set_text(id, fmt("paused=%d t=%.1f/%.1f muted=%d vol=%.1f loop=%d autoplay=%d ended=%d net=%d ready=%d",
                     media_paused(media), media_time(media), media->mediaDuration(), media->mediaMuted(),
                     media->mediaVolume(), media->mediaLoop(), media->mediaAutoplay(), media->mediaEnded(),
                     media->mediaNetworkState(), media->mediaReadyState()));
}

void on_aud_play() { g_aud->mediaPlay(); report_media("aud-out", g_aud); }
void on_aud_pause() { g_aud->mediaPause(); report_media("aud-out", g_aud); }
void on_aud_seek() { g_aud->mediaSetCurrentTime(3.0); report_media("aud-out", g_aud); }
void on_aud_mute() { g_aud->mediaSetMuted(!g_aud->mediaMuted()); report_media("aud-out", g_aud); }
void on_aud_loop() { g_aud->mediaSetLoop(!g_aud->mediaLoop()); report_media("aud-out", g_aud); }
void on_aud_load() { g_aud->mediaLoad(); report_media("aud-out", g_aud); }
void on_vid_play() { g_vid->mediaPlay(); report_media("vid-out", g_vid); }
void on_vid_pause() { g_vid->mediaPause(); report_media("vid-out", g_vid); }
void on_vid_seek() { g_vid->mediaSetCurrentTime(1.0); report_media("vid-out", g_vid); }

bool g_vid_controls = false;

void on_vid_controls() {
    g_vid_controls = !g_vid_controls;
    g_vid->mediaSetControls(g_vid_controls);
    report_media("vid-out", g_vid);
}

void on_vid_autoplay() {
    g_vid->mediaSetAutoplay(!g_vid->mediaAutoplay());
    report_media("vid-out", g_vid);
}

// Clicks on #id run `handler` (a missing button is reported as a failed check).
void on_click(const char* id, void (*handler)()) {
    kui::Element* button = g_doc->getElementById(id);
    if (!button) {
        check(std::string("ui.") + id, false, "button missing");
        return;
    }
    button->addEventListener("click", [handler, id](kui::Event&) {
        try {
            handler();
        } catch (const std::exception& error) {
            std::fprintf(stderr, "%s: %s\n", id, error.what());
        }
    });
}

}  // namespace

void tour_ready(kui::Window& window, kui::Document& document) {
    (void)window;
    g_doc = &document;
    find_paths();
    // Element pointers stay valid for the document's lifetime (its element cache owns them).
    g_aud = document.getElementById("aud");
    g_vid = document.getElementById("vid");
    g_lot = document.getElementById("lot");
    if (!g_aud || !g_vid || !g_lot) throw kui::Error(KUI_ERR_NOT_FOUND, "kui_api_media_lottie: page elements");

    g_lot->lottieSetSrc(g_lottie);
    g_lot->lottieSetLoop(true);
    g_lot->lottiePlay();

    run_group("audio", check_audio);
    run_group("audio", [] { check_media_setup("audio", g_aud, g_mp3); });
    run_group("video", [] { check_media_setup("video", g_vid, g_mp4); });
    run_group("media", check_media_not_media);
    kui::Platform::setTimeout([] { phase_one(); }, 300);

    on_click("btn-au-play", on_au_play);
    on_click("btn-au-pause", on_au_pause);
    on_click("btn-au-volume", on_au_volume);
    on_click("btn-au-pan", on_au_pan);
    on_click("btn-au-pitch", on_au_pitch);
    on_click("btn-au-seek", on_au_seek);
    on_click("btn-au-stop", on_au_stop);
    on_click("btn-au-sfx", on_au_sfx);
    on_click("btn-au-stopsfx", on_au_stopsfx);
    on_click("btn-au-pauseall", on_au_pauseall);
    on_click("btn-au-mute", on_au_mute);
    on_click("btn-au-preload", on_au_preload);
    on_click("btn-au-unload", on_au_unload);
    on_click("btn-lot-play", on_lot_play);
    on_click("btn-lot-pause", on_lot_pause);
    on_click("btn-lot-seek0", on_lot_seek0);
    on_click("btn-lot-seek50", on_lot_seek50);
    on_click("btn-lot-stop", on_lot_stop);
    on_click("btn-lot-speed", on_lot_speed);
    on_click("btn-lot-loop", on_lot_loop);
    on_click("btn-aud-play", on_aud_play);
    on_click("btn-aud-pause", on_aud_pause);
    on_click("btn-aud-seek", on_aud_seek);
    on_click("btn-aud-mute", on_aud_mute);
    on_click("btn-aud-loop", on_aud_loop);
    on_click("btn-aud-load", on_aud_load);
    on_click("btn-vid-play", on_vid_play);
    on_click("btn-vid-pause", on_vid_pause);
    on_click("btn-vid-seek", on_vid_seek);
    on_click("btn-vid-controls", on_vid_controls);
    on_click("btn-vid-autoplay", on_vid_autoplay);
}
// ---- end of examples/api_tours/media_lottie/host.cpp ----

int main() {
    try {
        if (!kui::Platform::init()) return 3;
        kui::WindowConfig config;
        config.title = "KUI API \xe2\x80\x94 audio, media elements & Lottie";
        config.width = 1100;
        config.height = 780;
        auto window = kui::Window::create(config);
        if (!window) return 4;
        kui::Document* document = window->document();
        auto script = kui::ScriptEngine::create();
        if (script) {
            script->setErrorHandler([](const std::string& error, const std::string& source, int line) {
                std::fprintf(stderr, "[Lua] %s:%d: %s\n", source.c_str(), line, error.c_str());
            });
            script->bindDocument(document);
            window->setScriptEngine(script.get());
        }
        tour_script = script.get();
        document->loadHTML(k_tour_page);
        if (script) script->executeScripts();
        // Test hook shared with the C / Go / Rust runners: KUI_EXAMPLE_DEVTOOLS_PORT=<port> starts
        // DevTools so scripts/verify_example_ports.py can click and read the DOM.
        const std::string port = tour_env("KUI_EXAMPLE_DEVTOOLS_PORT");
        if (!port.empty()) window->startDevTools(static_cast<kui::u16>(std::atoi(port.c_str())));
        tour_ready(*window, *document);
        const int code = kui::Platform::run();
        tour_script = nullptr;
        return code;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "[kui_api_media_lottie] %s\n", error.what());
        return 9;
    }
}
